// tests/scoring.test.ts
// Unit tests for lib/scoring.ts — spec §5.5, FR-RNK-01..03, NFR-QLT-02
//
// NOTE: These tests use inline minimal type stubs for InvestigationRecord and
// EnvironmentProfile because lib/schema.ts is generated by the data-layer
// worker. Once that file exists, the imports in lib/scoring.ts will resolve
// automatically; this test file uses cast helpers to avoid the dependency.

import { describe, expect, it } from "vitest";
import {
  rangeFit,
  fitO2,
  fitPsi,
  envFit,
  fitIss,
  fitMoon,
  relevance,
  sortRecords,
  round2,
  roundScore,
} from "@/lib/scoring";
import type { Weights } from "@/lib/scoring";

// ── Minimal stubs (match the real Zod-inferred shapes) ──────────────────────

type RangePair = { min: number; max: number };

type Env = {
  key: string;
  label: string;
  enabled: boolean;
  o2_pct: RangePair | null;
  pressure_psi: RangePair | null;
  source: string;
};

type Rec = {
  id: string;
  name: string;
  o2_min_pct: number | null;
  o2_max_pct: number | null;
  pressure_min_psi: number | null;
  pressure_max_psi: number | null;
  // lib/scoring only reads these four numeric fields plus `name`; the rest are
  // ignored by scoring logic, so we cast to the required type below.
  [key: string]: unknown;
};

// Cast helpers so TypeScript accepts our stubs without importing from schema.ts
// (which may not exist at the time this test file is first run).
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function asRecord(r: Rec): any {
  return r;
}
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function asEnvs(envs: Env[]): any[] {
  return envs;
}

// ── Shared ISS / Moon env fixtures ──────────────────────────────────────────

const ISS: Env = {
  key: "iss",
  label: "ISS",
  enabled: true,
  o2_pct: { min: 21, max: 21 },
  pressure_psi: { min: 14.7, max: 14.7 },
  source: "NASA",
};

const MOON: Env = {
  key: "moon_base",
  label: "Moon Base",
  enabled: true,
  o2_pct: { min: 30, max: 35 },
  pressure_psi: { min: 0, max: 10.2 },
  source: "NASA",
};

const DEFAULT_WEIGHTS: Weights = { iss: 0.5, moon_base: 0.5 };

// Helper: build a minimal InvestigationRecord
function makeRec(
  id: string,
  o2_min: number | null,
  o2_max: number | null,
  psi_min: number | null,
  psi_max: number | null,
  name?: string
): Rec {
  return {
    id,
    name: name ?? id,
    o2_min_pct: o2_min,
    o2_max_pct: o2_max,
    pressure_min_psi: psi_min,
    pressure_max_psi: psi_max,
  };
}

// ── Test 1: Worked example §5.4 ─────────────────────────────────────────────
// record: o2 [21,85], pressure [14.7,14.7]
// ISS: o2=[21,21], psi=[14.7,14.7] → fitO2=1.0, fitPsi=1.0 → envFit=1.0 → fitIss=1.00
// Moon: o2=[30,35], psi=[0,10.2]
//   fitO2: gap=max(0,30-85,21-35)=max(0,-55,-14)=0 → 1.0
//   fitPsi: gap=max(0,0-14.7,14.7-10.2)=max(0,-14.7,4.5)=4.5 > 3 → 0
//   envFit=(1+0)/2=0.5 → fitMoon=0.50
// score: (0.5×1 + 0.5×0.5)/(0.5+0.5) × 100 = (0.5+0.25)/1 × 100 = 75
describe("Worked example (spec §5.4)", () => {
  const rec = makeRec("r1", 21, 85, 14.7, 14.7);
  const envs = asEnvs([ISS, MOON]);
  const weights = DEFAULT_WEIGHTS;

  it("fitIss returns 1.00", () => {
    expect(fitIss(asRecord(rec), envs)).toBe(1.0);
  });

  it("fitMoon returns 0.50", () => {
    expect(fitMoon(asRecord(rec), envs)).toBe(0.5);
  });

  it("relevance score is 75 (FR-RNK-02)", () => {
    expect(relevance(asRecord(rec), envs, weights).score).toBe(75);
  });
});

// ── Test 2: Partial O2 fit ───────────────────────────────────────────────────
// O2 [25,28] vs ISS [21,21]: gap=max(0,21-28,25-21)=max(0,-7,4)=4
// fit=1-4/10=0.6
describe("Partial O2 fit (spec §5.5 T2)", () => {
  it("fit_o2 is 0.60 when record O2 [25,28] vs ISS [21,21]", () => {
    const rec = makeRec("r2", 25, 28, null, null);
    expect(fitO2(asRecord(rec), asEnvs([ISS])[0])).toBeCloseTo(0.6, 6);
  });
});

// ── Test 3: Partial pressure fit ────────────────────────────────────────────
// psi [12.0,12.0] vs ISS [14.7,14.7]: gap=14.7-12.0=2.7, fit=1-2.7/3=0.1
describe("Partial pressure fit (spec §5.5 T3)", () => {
  it("fit_psi is 0.1 when record pressure [12,12] vs ISS [14.7,14.7]", () => {
    const rec = makeRec("r3", null, null, 12.0, 12.0);
    expect(fitPsi(asRecord(rec), asEnvs([ISS])[0])).toBeCloseTo(0.1, 6);
  });
});

// ── Test 4: Gap beyond tolerance ────────────────────────────────────────────
// psi [14.7,14.7] vs Moon [0,10.2]: gap=max(0,0-14.7,14.7-10.2)=4.5 > 3 → 0
describe("Gap beyond tolerance (spec §5.5 T4)", () => {
  it("fit_psi is 0 when gap exceeds psi_tolerance", () => {
    const rec = makeRec("r4", null, null, 14.7, 14.7);
    expect(fitPsi(asRecord(rec), asEnvs([MOON])[0])).toBe(0);
  });
});

// ── Test 5: Single component (O2 null) ──────────────────────────────────────
// O2 null, psi [14.7,14.7] vs ISS → envFit = fitPsi = 1.0
describe("Single component fit (spec §5.5 T5)", () => {
  it("envFit equals fit_psi when O2 bounds are null", () => {
    const rec = makeRec("r5", null, null, 14.7, 14.7);
    const env = asEnvs([ISS])[0];
    const fp = fitPsi(asRecord(rec), env);
    const ef = envFit(asRecord(rec), env);
    expect(ef).toBe(fp);
    expect(ef).toBe(1.0);
  });
});

// ── Test 6: Both components null ────────────────────────────────────────────
describe("Both components null (spec §5.5 T6)", () => {
  const rec = makeRec("r6", null, null, null, null);

  it("envFit returns null when all bounds are null", () => {
    expect(envFit(asRecord(rec), asEnvs([ISS])[0])).toBeNull();
  });

  it("relevance score is null when env_fit is null", () => {
    expect(
      relevance(asRecord(rec), asEnvs([ISS, MOON]), DEFAULT_WEIGHTS).score
    ).toBeNull();
  });
});

// ── Test 7: Zero weight excluded ────────────────────────────────────────────
// ISS weight=1, Moon weight=0 → Moon row counted:false
// score = 100 × fitIss
describe("Zero weight excluded (spec §5.5 T7)", () => {
  const rec = makeRec("r7", 21, 85, 14.7, 14.7);
  const weights: Weights = { iss: 1, moon_base: 0 };
  const envs = asEnvs([ISS, MOON]);

  it("Moon row has counted:false", () => {
    const { rows } = relevance(asRecord(rec), envs, weights);
    const moon = rows.find((row) => row.env_key === "moon_base");
    expect(moon?.counted).toBe(false);
  });

  it("score equals 100 × fitIss (100)", () => {
    const { score } = relevance(asRecord(rec), envs, weights);
    expect(score).toBe(100);
  });
});

// ── Test 8: All weights zero ─────────────────────────────────────────────────
describe("All weights zero (spec §5.5 T8)", () => {
  it("score is null and weight_sum is 0", () => {
    const rec = makeRec("r8", 21, 85, 14.7, 14.7);
    const { score, weight_sum } = relevance(
      asRecord(rec),
      asEnvs([ISS, MOON]),
      { iss: 0, moon_base: 0 }
    );
    expect(score).toBeNull();
    expect(weight_sum).toBe(0);
  });
});

// ── Test 9: Half-up rounding to integer score ────────────────────────────────
// O2 [24.1,30], psi [14.1,14.1], ISS weight=1, Moon=0
// fit_o2: gap=max(0,21-30,24.1-21)=3.1, fit=1-3.1/10=0.69
// fit_psi: gap=max(0,14.7-14.1,14.1-14.7)=0.6, fit=1-0.6/3=0.80
// env_fit=(0.69+0.80)/2=0.745
// score=round(100×0.745/1)=round(74.5)=75 (half-up)
describe("Half-up rounding (spec §5.5 T9)", () => {
  it("score rounds 74.5 up to 75", () => {
    const rec = makeRec("r9", 24.1, 30, 14.1, 14.1);
    const weights: Weights = { iss: 1, moon_base: 0 };
    const { score } = relevance(asRecord(rec), asEnvs([ISS, MOON]), weights);
    expect(score).toBe(75);
  });
});

// ── Test 10: Disabled environment ────────────────────────────────────────────
// rover weight=1 but enabled=false → row NOT in relevance().rows
describe("Disabled environment (spec §5.5 T10)", () => {
  it("disabled env row does not appear in relevance rows", () => {
    const rover: Env = {
      key: "rover",
      label: "Mars Rover",
      enabled: false,
      o2_pct: { min: 0.1, max: 0.2 },
      pressure_psi: { min: 0.08, max: 0.12 },
      source: "NASA",
    };
    const rec = makeRec("r10", 21, 85, 14.7, 14.7);
    const { rows } = relevance(asRecord(rec), asEnvs([ISS, rover]), {
      iss: 1,
      rover: 1,
    });
    expect(rows.find((row) => row.env_key === "rover")).toBeUndefined();
    // ISS row still present
    expect(rows.find((row) => row.env_key === "iss")).toBeDefined();
  });
});

// ── Test 11: Tie-break by scoring-field count ────────────────────────────────
// Two records with equal integer score; recA has both O2 and psi (count=2),
// recB has only psi (count=1). recA should sort first (FR-RNK-03).
describe("Tie-break by scoring-field count (spec §5.5 T11)", () => {
  it("record with 2 scoring fields sorts before record with 1 (equal score)", () => {
    // Build envs where both records get the same integer score
    // recA: O2 [21,21] psi [14.7,14.7] → fitIss=1, fitMoon=fitPsi(0)=0 → avg=0.5 → score=50 (w=0.5/0.5)
    // recB: O2 null, psi [14.7,14.7] → fitIss: envFit=fitPsi=1 → fitMoon: fitPsi=0, no O2 → envFit=0 → avg=0.5 → score=50
    // Both score 50 with equal weights; recA has count=2, recB has count=1
    const recA = makeRec("a", 21, 21, 14.7, 14.7, "alpha");
    const recB = makeRec("b", null, null, 14.7, 14.7, "beta");
    const sorted = sortRecords(
      [asRecord(recB), asRecord(recA)],
      asEnvs([ISS, MOON]),
      DEFAULT_WEIGHTS
    );
    expect(sorted[0].id).toBe("a");
    expect(sorted[1].id).toBe("b");
  });
});

// ── Test 12: Unscored last ───────────────────────────────────────────────────
// A record with null O2 and null pressure → score null → sorts after scored records
describe("Unscored sorts last (spec §5.5 T12)", () => {
  it("null-scoring record sorts after scored records regardless of direction", () => {
    const scored = makeRec("s", 21, 21, 14.7, 14.7, "alpha");
    const unscored = makeRec("u", null, null, null, null, "zeta");
    // Ascending name would put "alpha" before "zeta", but scoring takes priority
    const sorted = sortRecords(
      [asRecord(unscored), asRecord(scored)],
      asEnvs([ISS, MOON]),
      DEFAULT_WEIGHTS
    );
    expect(sorted[0].id).toBe("s");
    expect(sorted[1].id).toBe("u");
  });
});

// ── Test 13: fitMoon rounds half-up to 2 dp ──────────────────────────────────
// If envFit = 0.345 → round2 → 0.35 (half-up at the second decimal)
describe("fitMoon rounds to 2 dp half-up (spec §5.5 T13)", () => {
  it("round2(0.345) is 0.35", () => {
    expect(round2(0.345)).toBe(0.35);
  });

  it("fitMoon of a record whose moon envFit is 0.345 returns 0.35", () => {
    // Design: fit_o2=1.0 (O2 matches Moon [30,35] exactly: [30,35])
    //         fit_psi: gap=max(0,0-X, X-10.2) must give (1.0+fit_psi)/2=0.345 → fit_psi=-0.31 → clamp 0
    // Easier: craft values so fit_psi is exactly 0 and fit_o2=0.69 → avg=0.345
    // fit_o2=0.69: gap=3.1, record O2=[30,30+3.1] = [30,33.1], Moon O2=[30,35] → gap=max(0,30-33.1,30-30)=0 → fit_o2=1 (nope)
    // Let's approach differently:
    //   MOON: o2=[30,35], psi=[0,10.2]
    //   Want envFit=0.345 = (fit_o2 + fit_psi)/2
    //   Set fit_o2=0.69, fit_psi=0.00 → avg=0.345 ✓
    //   fit_o2=0.69: gap=max(0,30-o2max, o2min-35)=3.1, so o2max-o2min such that:
    //     e.g. o2min=35, o2max=35: gap=max(0,30-35,35-35)=0 → fit=1 (no)
    //   Try: o2min=38.1, o2max=38.1 → gap=max(0,30-38.1,38.1-35)=max(0,-8.1,3.1)=3.1 → fit=1-3.1/10=0.69 ✓
    //   fit_psi=0: psi=[14.7,14.7] → gap=max(0,0-14.7,14.7-10.2)=4.5>3 → 0 ✓
    // So record o2=[38.1,38.1], psi=[14.7,14.7] → envFit(Moon)=(0.69+0)/2=0.345 → fitMoon=0.35
    const moonEnv: Env = {
      key: "moon_base",
      label: "Moon Base",
      enabled: true,
      o2_pct: { min: 30, max: 35 },
      pressure_psi: { min: 0, max: 10.2 },
      source: "NASA",
    };
    const rec = makeRec("r13", 38.1, 38.1, 14.7, 14.7);
    const result = fitMoon(asRecord(rec), asEnvs([ISS, moonEnv]));
    expect(result).toBe(0.35);
  });
});

// ── Extra: primitive helper coverage ────────────────────────────────────────
describe("rangeFit primitive (spec §5.2)", () => {
  it("full overlap returns 1", () => {
    expect(rangeFit({ min: 10, max: 20 }, { min: 12, max: 18 }, 5)).toBe(1);
  });

  it("gap equal to tolerance returns 0", () => {
    expect(rangeFit({ min: 20, max: 20 }, { min: 10, max: 10 }, 10)).toBe(0);
  });
});

describe("roundScore", () => {
  it("rounds 74.5 up to 75", () => {
    expect(roundScore(74.5)).toBe(75);
  });

  it("rounds 74.4 down to 74", () => {
    expect(roundScore(74.4)).toBe(74);
  });
});
